import{_ as t,o as n,c as i,a3 as r}from"./chunks/framework.BlfGB29P.js";const p=JSON.parse('{"title":"","description":"","frontmatter":{"layout":"home","hero":{"name":"Parcel to MQTT","text":"Entwicklung eingestellt","tagline":"Parcel Tracker ist bereits deutlich weiter entwickelt. Deshalb stellen wir die Weiterentwicklung von Parcel to MQTT ein. Die bisherige Dokumentation bleibt als Archiv erhalten.","actions":[{"theme":"brand","text":"Parcel Tracker ansehen","link":"https://github.com/SoerenKaiser99/parcel_tracker"},{"theme":"alt","text":"GitHub","link":"https://github.com/rockbaer2007/ugso-ha-mqtt-addons/tree/master/parcel_to_mqtt"}]},"features":[{"icon":"📦","title":"Paketstatus","details":"Paketstatus, letztes Ereignis, Ziel und Sendungsnummer als Home-Assistant-Entitäten."},{"icon":"🚚","title":"DHL und Hermes aktiv","details":"DHL-Kontoliste, manuelle DHL-Sendungsnummern und Hermes-Sendungsverfolgung."},{"icon":"🧩","title":"Anbieterbereiche","details":"Gruppierte Einstellungen für DHL, Hermes, GLS, DPD, UPS, Amazon Logistics, Deutsche Post Briefe und FedEx."},{"icon":"📊","title":"Zähler und Slots","details":"Zähler für Gesamt, unterwegs, in Zustellung, Abholstelle, zugestellt, Rücksendung, Problem und unbekannt."},{"icon":"🏠","title":"MQTT Discovery","details":"Home Assistant legt Paket-, Status- und Zähler-Entitäten automatisch an."},{"icon":"🔔","title":"Automationen","details":"Benachrichtigungen werden über normale Home-Assistant-Automationen auf Basis der erzeugten Entitäten gebaut."}]},"headers":[],"relativePath":"projects/parcel-to-mqtt/index.md","filePath":"projects/parcel-to-mqtt/index.md","lastUpdated":1792783045000}'),a={name:"projects/parcel-to-mqtt/index.md"};function l(s,e,o,u,c,d){return n(),i("div",null,[...e[0]||(e[0]=[r('<div class="warning custom-block"><p class="custom-block-title">Entwicklung eingestellt</p><p>Parcel Tracker ist bereits deutlich weiter entwickelt. Deshalb stellen wir die Weiterentwicklung von Parcel to MQTT ein und empfehlen Interessierten einen Blick auf <a href="https://github.com/SoerenKaiser99/parcel_tracker" target="_blank" rel="noreferrer">Parcel Tracker von SoerenKaiser99</a>.</p><p>Quellcode und bisherige Dokumentation bleiben als Archiv erhalten. Die folgenden Funktionen und Anleitungen beschreiben den letzten Stand unseres Pakets.</p></div><h2 id="uberblick" tabindex="-1">Überblick <a class="header-anchor" href="#uberblick" aria-label="Permalink to &quot;Überblick&quot;">​</a></h2><p>Parcel to MQTT ist eine Home-Assistant-App, die Paketverfolgung per MQTT Discovery in Home Assistant bereitstellt.</p><p>Die aktuelle Version nutzt DHL-Konto-Paketlisten, optionale manuelle DHL-Sendungsnummern und Hermes-Paketverfolgung. Die App-Einstellungen sind nach Dienstleistern gruppiert, damit die Home-Assistant-Konfiguration kompakt als Anbieterbereiche erscheint.</p><div class="info custom-block"><p class="custom-block-title">Ursprung</p><p>Die Umsetzung ist adaptiert von und inspiriert durch den ioBroker-Adapter <a href="https://github.com/TA2k/ioBroker.parcel" target="_blank" rel="noreferrer">TA2k/ioBroker.parcel</a>.</p><p>Das gemeinsame Statusmodell ist inspiriert durch die MIT-lizenzierten Home-Assistant-Paketintegrationen <a href="https://github.com/ha-parcel-integrations" target="_blank" rel="noreferrer">ha-parcel-integrations</a>.</p></div><h2 id="fruhere-provider-roadmap-archiv" tabindex="-1">Frühere Provider-Roadmap (Archiv) <a class="header-anchor" href="#fruhere-provider-roadmap-archiv" aria-label="Permalink to &quot;Frühere Provider-Roadmap (Archiv)&quot;">​</a></h2><p>Die folgenden Punkte beschreiben den bisherigen Entwicklungsstand und frühere Pläne. Diese Roadmap wird nicht mehr umgesetzt:</p><ul><li>DHL: aktiv über <code>dhllogin://</code> Browser-Login-Code plus optionale manuelle Sendungsnummern</li><li>Amazon: vorbereitet mit E-Mail, Passwort und optionalem OTP-Token</li><li>Hermes: aktuell per manueller Sendungsnummer aktiv; Konto-Login mit App-Username und App-Passwort ist geplant</li><li>UPS: vorbereitet mit App-Username, App-Passwort und manuellen Sendungsnummern</li><li>GLS: vorbereitet mit manuellen Sendungsnummern und Liefer-Postleitzahl; Polling wartet auf eine stabile Guest-Bearer-Session</li><li>DPD: vorbereitet mit Username, Passwort und manuellen Sendungsnummern, sobald der stabile Login-/Session-Ablauf sauber abgebildet ist</li><li>Deutsche Post Briefe und FedEx: vorbereitet mit manuellen Sendungsnummern für spätere Connectoren</li></ul><h2 id="weitere-seiten" tabindex="-1">Weitere Seiten <a class="header-anchor" href="#weitere-seiten" aria-label="Permalink to &quot;Weitere Seiten&quot;">​</a></h2><ul><li><a href="./installation">Installation</a></li><li><a href="./konfiguration">Konfiguration</a></li><li><a href="./entitaeten">Entitäten</a></li><li><a href="./beispiele">Beispiele</a></li></ul>',10)])])}const h=t(a,[["render",l]]);export{p as __pageData,h as default};
